async function requestMicrophoneOnLaunch() {
  if (!navigator.mediaDevices?.getUserMedia) return;
  try {
    const permission = await navigator.permissions?.query?.({ name: 'microphone' });
    if (permission?.state === 'denied') { setCaptureToggle('microphone', false, 'Microphone permission blocked. Allow access in the browser site controls, then select Connect microphone.'); return; }
    await enableMic();
  } catch { await enableMic(); }
}

