function renderTranscriptProvenance() { let summary = $('transcript-provenance'); if (!summary) { summary = document.createElement('p'); summary.id = 'transcript-provenance'; summary.className = 'transcript-provenance'; document.querySelector('.transcript-controls').after(summary); } summary.hidden = !session; summary.textContent = `${transcriptProvenance().model} · ${selectedLanguage || 'English'} · Audio processing ${audioProcessingEnabled ? 'on' : 'off'} · Generated with CallScribe`; }
