// result is used in HTML attributes for screenshot descriptions.
function escapeHtml(value) { const element = document.createElement('span'); element.textContent = String(value ?? ''); return element.innerHTML.replace(/"/g, '&#34;').replace(/'/g, '&#39;'); }
function minutesHtmlBody(content, figures, used) { const marker = /^\[\[screenshot:([^\]]+)\]\]$/; const blocks = []; let list = []; const flushList = () => { if (list.length) blocks.push(`<ul>${list.map((item) => `<li>${item}</li>`).join('')}</ul>`); list = []; }; for (const line of content.split('\n')) { const match = line.match(marker); if (match && figures.has(match[1])) { flushList(); used.add(match[1]); blocks.push(figures.get(match[1])); continue; } const safe = escapeHtml(line); if (safe.startsWith('- ')) { list.push(safe.slice(2)); continue; } flushList(); if (safe.startsWith('# ')) blocks.push(`<h1>${safe.slice(2)}</h1>`); else if (safe.startsWith('## ')) blocks.push(`<h2>${safe.slice(3)}</h2>`); else if (safe) blocks.push(`<p>${safe}</p>`); } flushList(); return blocks.join('\n'); }
async function minutesHtml() { if (!minutesNote) throw new Error('Generate or open meeting notes first.'); const note = { ...minutesNote, title: ui['minutes-title'].value.trim() || minutesNote.title, content: notesExportContent(minutesNote) }; const shots = (await sessionScreenshots()).filter((shot) => note.screenshotIds?.includes(shot.id)); const figures = new Map(await Promise.all(shots.map(async (shot) => [shot.id, `<figure><img src="${await blobToDataUrl(shot.blob)}" alt="${escapeHtml(shot.ocrText || `Screenshot captured ${formatDateTime(shot.capturedAt)}`)}"><figcaption>Screenshot captured ${escapeHtml(formatDateTime(shot.capturedAt))}${shot.ocrText ? `: ${escapeHtml(shot.ocrText)}` : ''}</figcaption></figure>`]))); const used = new Set(); const body = minutesHtmlBody(note.content, figures, used); const remaining = [...figures].filter(([id]) => !used.has(id)).map(([, figure]) => figure).join(''); return `<!doctype html><html lang="en"><meta charset="utf-8"><title>${escapeHtml(note.title)}</title><style>body{font:12pt/1.5 system-ui,sans-serif;max-width:52rem;margin:2rem auto;padding:0 1rem;color:#111}h1,h2{line-height:1.2}figure{margin:1.5rem 0;break-inside:avoid}img{max-width:100%;height:auto}figcaption{font-size:.9em}@media print{body{max-width:none;margin:0}h1,h2{break-after:avoid}}</style><body>${body}${remaining}</body></html>`; }
async function screenshotImageForDocx(shot) { const bitmap = await createImageBitmap(shot.blob); const canvas = document.createElement('canvas'); canvas.width = bitmap.width; canvas.height = bitmap.height; canvas.getContext('2d').drawImage(bitmap, 0, 0); bitmap.close(); const png = await new Promise((resolve) => canvas.toBlob(resolve, 'image/png')); if (!png) throw new Error('Could not convert a selected screenshot for Word export.'); return { data: new Uint8Array(await png.arrayBuffer()), width: canvas.width, height: canvas.height }; }
